const LIST_KEYS = ['jobs', 'results', 'data', 'items', 'posts'];
const raw = $input.all().map(i => i.json);
const list = [];
for (const r of raw) {
  if (Array.isArray(r)) list.push(...r);
  else if (r && typeof r === 'object') {
    const k = LIST_KEYS.find(k => Array.isArray(r[k]));
    if (k) list.push(...r[k]);
    else list.push(r);
  } else if (r !== null && r !== undefined) list.push(r);
}

const pick = (...v) => v.find(x => x !== undefined && x !== null && x !== '') || '';
const hash = s => {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  return (h >>> 0).toString(16).padStart(8, '0');
};

const seenUrls = new Set();
const seenKeys = new Set();
const out = [];
for (const job of list) {
  if (!job || typeof job !== 'object') continue;
  const company  = pick(job.company_name, job.company, job.author);
  const title    = pick(job.title, job.job_title, job.position);
  const location = pick(job.city, job.location, job.candidate_required_location);
  if (!company && !title) continue;
  const url    = pick(job.url, job.job_url, job.apply_url);
  const jd     = pick(job.description, job.body, job.job_description);
  const source = job.source || job.site || 'scraped';
  const posted = pick(job.date_posted, job.pubDate, job.date, job.created_at);

  const normUrl = String(url).trim().toLowerCase().replace(/\/+$/, '');
  if (normUrl && seenUrls.has(normUrl)) continue;
  if (normUrl) seenUrls.add(normUrl);
  const key = `${company.toLowerCase().trim()}|${title.toLowerCase().trim()}|${location.toLowerCase().trim()}`;
  if (seenKeys.has(key)) continue;
  seenKeys.add(key);

  out.push({
    job_id: hash(normUrl || key),
    company, title, location,
    company_url: pick(job.company_url, job.employer_url),
    experience: '',
    job_url: url,
    jd: String(jd).slice(0, 4000),
    source,
    posted_date: posted,
    discovered_date: new Date().toISOString()
  });
}

// ponytail: LLM is 60s/call on CPU, so prefilter + cap before spending LLM time.
const MOBILE = /(flutter|android|\bios\b|iphone|swift|kotlin|mobile app|react native|\bdart\b|jetpack|mvvm|mvp|firebase|app development|app store|google play|android studio|xcode)/i;
const STRONG = /(flutter|android|ios|iphone|swift|kotlin|react native|mobile app)/i;
for (const j of out) j._rel = (STRONG.test(j.title) ? 2 : 0) + (MOBILE.test(j.title + ' ' + j.jd) ? 1 : 0);
const relevant = out.filter(j => j._rel > 0).sort((a, b) => b._rel - a._rel);
const LLM_BUDGET = 12;
const keep = (relevant.length ? relevant : out).slice(0, LLM_BUDGET);
for (const j of keep) delete j._rel;
return keep;

